15	/// Kinds of uniqueness conflicts a repository can report (D7: never surface raw backend text).
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum ConflictKind {
18	    SlugTaken,
19	    DuplicateMembership,
20	    EmailTaken,
21	    ExternalIdentityExists,
22	    Other,
23	}
24	
25	/// Kinds of precondition failures a repository can report (in-txn guards, D8/D10).
26	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
27	pub enum PreconditionKind {
28	    ParentArchived,
29	    NodeArchived,
30	    MissingOrgMembership,
31	}
32	
33	/// Persistence errors, source-preserving. The adapter maps its backend error (e.g. SeaORM
34	/// `DbErr`) into these; the core never imports the backend.
35	#[derive(Debug, thiserror::Error)]
36	pub enum RepositoryError {
37	    #[error("conflict: {0:?}")]
38	    Conflict(ConflictKind),
39	    #[error("not found")]
40	    NotFound,
41	    #[error("prn does not match stored resource")]
42	    PrnMismatch,
43	    #[error("precondition failed: {0:?}")]
44	    Precondition(PreconditionKind),
45	    #[error("backend error")]
46	    Backend(#[from] Box<dyn std::error::Error + Send + Sync>),
47	}
48	
49	/// A tenancy node together with its effective status (own status folded with ancestors, D1/D10).
50	#[derive(Debug, Clone, PartialEq, Eq)]
51	pub struct NodeView<T> {
52	    pub node: T,
53	    pub effective_status: NodeStatus,
54	}
55	
56	/// A persisted membership row (D5: plain UUIDv7 id, no PRN).
57	#[derive(Debug, Clone, PartialEq, Eq)]
58	pub struct MembershipRecord {
59	    pub id: Uuid,
60	    pub principal_prn: String,
61	    pub node_prn: String,
62	    pub created_at: DateTime<Utc>,
63	}
64	
65	/// Persistence port for user-principals.
66	#[async_trait]
67	pub trait PrincipalRepository: Send + Sync {
68	    async fn create_user(&self, principal: &Principal, user: &User) -> Result<(), RepositoryError>;
69	    async fn find_user(&self, id: &PrincipalId) -> Result<Option<(Principal, User)>, RepositoryError>;
70	    async fn find_principal(&self, id: &PrincipalId) -> Result<Option<Principal>, RepositoryError>;
71	}
72	
73	/// Persistence port for external (IdP) identities linked to a principal.
74	#[async_trait]
75	pub trait ExternalIdentityRepository: Send + Sync {
76	    async fn find_by_issuer_subject(&self, issuer: &Issuer, subject: &str) -> Result<Option<ExternalIdentity>, RepositoryError>;
77	    /// One transaction spanning principal + user + external_identity (D9).
78	    async fn provision(&self, principal: &Principal, user: &User, identity: &ExternalIdentity) -> Result<(), RepositoryError>;
79	}
80	
81	/// Persistence port for organizations.
82	#[async_trait]
83	pub trait OrganizationRepository: Send + Sync {
84	    /// One transaction: org + auto-provisioned default team (ADR-0014).
85	    async fn create(&self, org: &Organization, default_team: &Team) -> Result<(), RepositoryError>;
86	    async fn find(&self, id: Uuid) -> Result<Option<NodeView<Organization>>, RepositoryError>;
87	    /// ORDER BY created_at, id (rule 9).
88	    async fn list(&self, limit: u64, offset: u64) -> Result<Vec<NodeView<Organization>>, RepositoryError>;
89	    /// In-txn guard: NotFound if missing; Precondition(NodeArchived) if own status archived.
90	    async fn rename(&self, id: Uuid, new_slug: Option<&Slug>, new_name: Option<&str>, now: DateTime<Utc>) -> Result<NodeView<Organization>, RepositoryError>;
91	    /// Sets own status (D10). Idempotent: no-op (updated_at untouched) when already `status`.
92	    async fn set_status(&self, id: Uuid, status: NodeStatus, now: DateTime<Utc>) -> Result<NodeView<Organization>, RepositoryError>;
93	}
94	
95	/// Persistence port for teams.
96	#[async_trait]
97	pub trait TeamRepository: Send + Sync {
98	    /// In-txn guards (D8): org row locked FOR SHARE; NotFound if org missing;
99	    /// Precondition(ParentArchived) if org effectively archived.
100	    async fn create(&self, team: &Team) -> Result<(), RepositoryError>;
101	    async fn find(&self, id: Uuid) -> Result<Option<NodeView<Team>>, RepositoryError>;
102	    async fn list_by_org(&self, org: Uuid, limit: u64, offset: u64) -> Result<Vec<NodeView<Team>>, RepositoryError>;
103	    /// Guard: Precondition(NodeArchived) if team is EFFECTIVELY archived (own or org).
104	    async fn rename(&self, id: Uuid, new_slug: Option<&Slug>, new_name: Option<&str>, now: DateTime<Utc>) -> Result<NodeView<Team>, RepositoryError>;
105	    async fn set_status(&self, id: Uuid, status: NodeStatus, now: DateTime<Utc>) -> Result<NodeView<Team>, RepositoryError>;
106	}
107	
108	/// Persistence port for projects.
109	#[async_trait]
110	pub trait ProjectRepository: Send + Sync {
111	    /// In-txn guards: team+org locked FOR SHARE; NotFound if team missing; Precondition(ParentArchived)
112	    /// if team effectively archived; Backend if project.org != team.org (belt-and-braces, composite FK).
113	    async fn create(&self, project: &Project) -> Result<(), RepositoryError>;
114	    async fn find(&self, id: Uuid) -> Result<Option<NodeView<Project>>, RepositoryError>;
115	    async fn list_by_team(&self, team: Uuid, limit: u64, offset: u64) -> Result<Vec<NodeView<Project>>, RepositoryError>;
116	    async fn rename(&self, id: Uuid, new_slug: Option<&Slug>, new_name: Option<&str>, now: DateTime<Utc>) -> Result<NodeView<Project>, RepositoryError>;
117	    async fn set_status(&self, id: Uuid, status: NodeStatus, now: DateTime<Utc>) -> Result<NodeView<Project>, RepositoryError>;
118	}
119	
120	/// Persistence port for memberships.
121	#[async_trait]
122	pub trait MembershipRepository: Send + Sync {
123	    /// One transaction, all guards in-txn with FOR SHARE locks (D8, rule 8):
124	    /// principal exists + stored-prn byte-match (else NotFound / PrnMismatch);
125	    /// node exists + stored-prn byte-match; node effectively active (else Precondition(NodeArchived));
126	    /// team/project targets: org membership exists, locked (else Precondition(MissingOrgMembership));
127	    /// duplicate -> Conflict(DuplicateMembership).
128	    async fn attach(&self, membership: &Membership) -> Result<MembershipRecord, RepositoryError>;
129	    async fn find(&self, id: Uuid) -> Result<Option<MembershipRecord>, RepositoryError>;
130	    /// NotFound if missing. Org memberships cascade: also deletes the principal's
131	    /// team/project memberships in that org, one transaction (rule 5).
132	    async fn detach(&self, id: Uuid) -> Result<(), RepositoryError>;
133	    async fn list_by_principal(&self, principal: Uuid, limit: u64, offset: u64) -> Result<Vec<MembershipRecord>, RepositoryError>;
134	    /// Resolves node by uuid; PrnMismatch if the supplied ref's canonical != stored prn; NotFound if absent.
135	    async fn list_by_node(&self, node: &TenancyNodeRef, limit: u64, offset: u64) -> Result<Vec<MembershipRecord>, RepositoryError>;
136	}
137	
138	/// Mints new identities (UUIDv7 + PRN). Impure (clock + entropy) — hence a port.
139	pub trait IdGenerator: Send + Sync {
140	    fn new_principal_id(&self) -> PrincipalId;
141	    fn new_organization_id(&self) -> OrganizationId;
142	    fn new_team_id(&self, org: Uuid) -> TeamId;
143	    fn new_project_id(&self, org: Uuid) -> ProjectId;
144	    fn new_membership_id(&self) -> Uuid;
145	    fn new_external_identity_id(&self) -> Uuid;
146	}
