148	/// A source of the current time, truncated to microseconds so values round-trip through
149	/// Postgres `TIMESTAMPTZ` (µs resolution) bit-for-bit.
150	pub trait Clock: Send + Sync {
151	    fn now(&self) -> DateTime<Utc>;
152	}
153	
154	/// Verifies a presented bearer token and extracts its claims.
155	#[async_trait]
156	pub trait Authenticator: Send + Sync {
157	    /// The pluggable port (ADR-0015). OIDC validator is the v1 impl.
158	    async fn authenticate(&self, token: &str) -> Result<ValidatedClaims, AuthnError>;
159	}
