3	//! Service configuration via figment: built-in defaults < `iam.toml` < `IAM_*` env.
4	
5	use figment::providers::{Env, Format, Serialized, Toml};
6	use figment::{Figment, error::Error as FigmentError};
7	use paigasus_iam_core::Issuer;
8	use serde::{Deserialize, Serialize};
9	use std::collections::HashSet;
10	use std::net::SocketAddr;
11	
12	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
13	pub struct IamConfig {
14	    pub http_addr: SocketAddr,
15	    pub grpc_addr: SocketAddr,
16	    pub database_url: String,
17	    pub log_level: String,
18	    pub authn: AuthnConfig,
19	}
20	
21	/// BYO-IdP OIDC authentication config (spec §6.4). `issuers` is intentionally left
22	/// without a default (see `AuthnDefaults` below) — same "hard error when missing"
23	/// treatment as `IamConfig::database_url`.
24	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
25	pub struct AuthnConfig {
26	    pub leeway_secs: u64,
27	    pub http_timeout_secs: u64,
28	    pub jwks_ttl_secs: u64,
29	    pub jwks_refresh_cooldown_secs: u64,
30	    pub max_token_bytes: usize,
31	    /// TEST-ONLY escape hatch for self-signed IdP TLS: when `true`, certificate
32	    /// verification is DISABLED for the discovery/JWKS fetches (`reqwest`'s
33	    /// `danger_accept_invalid_certs`). NEVER enable this in production — it lets any
34	    /// on-path attacker serve a forged JWKS, which is a full authentication bypass.
35	    /// Exists solely so the integration suites (in-process mock IdP, Keycloak-in-Docker,
36	    /// SMA-443 Tasks 10/13) can fetch from HTTPS endpoints with self-signed dev certs.
37	    #[serde(default)]
38	    pub accept_invalid_tls: bool,
39	    pub jwks_cache: JwksCacheConfig,
40	    pub issuers: Vec<IssuerConfig>,
41	}
42	
43	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
44	pub struct JwksCacheConfig {
45	    pub backend: JwksCacheBackend,
46	    pub redis_url: Option<String>,
47	}
48	
49	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
50	#[serde(rename_all = "lowercase")]
51	pub enum JwksCacheBackend {
52	    Memory,
53	    Redis,
54	}
55	
56	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
57	pub struct IssuerConfig {
58	    pub issuer: String,
59	    pub audiences: Vec<String>,
60	    #[serde(default = "default_jit_provisioning")]
61	    pub jit_provisioning: bool,
62	}
63	
64	fn default_jit_provisioning() -> bool {
65	    true
66	}
