68	// Only the fields that HAVE a default. `database_url` and `authn.issuers` are
69	// intentionally absent so a missing value is a hard error at load time.
70	#[derive(Serialize)]
71	struct Defaults {
72	    http_addr: SocketAddr,
73	    grpc_addr: SocketAddr,
74	    log_level: String,
75	    authn: AuthnDefaults,
76	}
77	
78	// Mirrors `AuthnConfig` minus `issuers` — deliberately absent, see `AuthnConfig` doc.
79	#[derive(Serialize)]
80	struct AuthnDefaults {
81	    leeway_secs: u64,
82	    http_timeout_secs: u64,
83	    jwks_ttl_secs: u64,
84	    jwks_refresh_cooldown_secs: u64,
85	    max_token_bytes: usize,
86	    accept_invalid_tls: bool,
87	    jwks_cache: JwksCacheConfig,
88	}
89	
90	impl Default for Defaults {
91	    fn default() -> Self {
92	        Defaults {
93	            http_addr: "0.0.0.0:8080".parse().expect("valid addr"),
94	            grpc_addr: "0.0.0.0:9090".parse().expect("valid addr"),
95	            log_level: "info".to_string(),
96	            authn: AuthnDefaults::default(),
97	        }
98	    }
99	}
100	
101	impl Default for AuthnDefaults {
102	    fn default() -> Self {
103	        AuthnDefaults {
104	            leeway_secs: 60,
105	            http_timeout_secs: 10,
106	            jwks_ttl_secs: 3600,
107	            jwks_refresh_cooldown_secs: 30,
108	            max_token_bytes: 16384,
109	            accept_invalid_tls: false,
110	            jwks_cache: JwksCacheConfig {
111	                backend: JwksCacheBackend::Memory,
112	                redis_url: None,
113	            },
114	        }
