3	//! paigasus-iam composition root: load config, init logging, connect + migrate the DB,
4	//! serve HTTP + gRPC health on two ports, and shut down gracefully on SIGINT/SIGTERM.
5	
6	use std::time::Duration;
7	
8	use paigasus_iam::adapters::http::{AppState, serve_http};
9	use paigasus_iam::adapters::{grpc, persistence::Migrator};
10	use paigasus_iam::config::IamConfig;
11	use sea_orm::Database;
12	use sea_orm_migration::MigratorTrait;
13	use tokio::task::JoinSet;
14	
15	#[tokio::main]
16	async fn main() -> anyhow::Result<()> {
17	    let config = IamConfig::load()?;
18	    config.validate().map_err(|e| anyhow::anyhow!(e))?;
19	    paigasus_logging::init("paigasus-iam", &config.log_level);
20	
21	    let db = Database::connect(&config.database_url).await?;
22	    Migrator::up(&db, None).await?;
23	    // Built once and cloned into each server task below (a cheap handle-clone: every
24	    // per-aggregate service just wraps the same underlying connection pool, and the wired
25	    // authenticator's JWKS cache/single-flight state is `Arc`-shared) — HTTP and gRPC
26	    // share one `AppState` (Task 16, SMA-442; authn wiring SMA-443). Fails fast when the
27	    // Redis JWKS cache is configured but unreachable; JWKS themselves are fetched lazily
28	    // on first use, so startup stays independent of IdP availability (spec §6.4).
29	    let state = AppState::new(db, &config).await?;
30	
31	    let request_timeout = Duration::from_secs(30);
32	    let (tx, rx) = tokio::sync::watch::channel(());
33	
34	    let mut servers: JoinSet<anyhow::Result<()>> = JoinSet::new();
35	    {
36	        let mut rx = rx.clone();
37	        let state = state.clone();
38	        let addr = config.http_addr;
39	        servers.spawn(async move {
40	            serve_http(addr, state, request_timeout, async move {
41	                let _ = rx.changed().await;
42	            })
43	            .await
44	            .map_err(anyhow::Error::from)
45	        });
46	    }
47	    {
48	        let mut rx = rx.clone();
49	        let state = state.clone();
50	        let addr = config.grpc_addr;
51	        servers.spawn(async move {
52	            grpc::serve(addr, state, request_timeout, async move {
53	                let _ = rx.changed().await;
54	            })
55	            .await
56	            .map_err(anyhow::Error::from)
57	        });
58	    }
59	
60	    tracing::info!(%config.http_addr, %config.grpc_addr, "paigasus-iam started");
61	
62	    // Stop on the first of: shutdown signal, or a server task ending.
63	    let early_error: Option<anyhow::Error> = tokio::select! {
64	        () = shutdown_signal() => {
65	            tracing::info!("shutdown signal received");
66	            None
67	        }
68	        Some(joined) = servers.join_next() => {
69	            match joined {
70	                Ok(Ok(())) => {
71	                    tracing::warn!("a server task exited before shutdown was requested");
72	                    None
73	                }
74	                Ok(Err(e)) => {
75	                    tracing::error!(error = %e, "a server task failed");
76	                    Some(e)
77	                }
78	                Err(join_err) => {
79	                    tracing::error!(error = %join_err, "a server task panicked");
80	                    Some(join_err.into())
81	                }
82	            }
83	        }
84	    };
85	
86	    // Ask any still-running server to shut down gracefully.
87	    let _ = tx.send(());
88	
89	    // Drain the remaining server task(s); surface the first error.
90	    let mut result = early_error.map_or(Ok(()), Err);
91	    while let Some(joined) = servers.join_next().await {
92	        match joined {
93	            Ok(Ok(())) => {}
94	            Ok(Err(e)) if result.is_ok() => result = Err(e),
95	            Ok(Err(_)) => {}
96	            Err(join_err) if result.is_ok() => result = Err(join_err.into()),
97	            Err(_) => {}
98	        }
99	    }
100	    result
101	}
102	
103	async fn shutdown_signal() {
104	    let ctrl_c = async {
105	        tokio::signal::ctrl_c().await.expect("install Ctrl+C handler");
106	    };
107	    #[cfg(unix)]
108	    let terminate = async {
109	        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("install SIGTERM handler").recv().await;
110	    };
111	    #[cfg(not(unix))]
112	    let terminate = std::future::pending::<()>();
113	
114	    tokio::select! {
115	        () = ctrl_c => {},
116	        () = terminate => {},
117	    }
118	}
