17	impl Slug {
18	    pub fn parse(input: &str) -> Result<Self, DomainError> {
19	        let ok_len = !input.is_empty() && input.len() <= SLUG_MAX_LEN;
20	        let ok_chars = input.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
21	        let ok_edges = !input.starts_with('-') && !input.ends_with('-') && !input.contains("--");
22	        if ok_len && ok_chars && ok_edges {
23	            Ok(Self(input.to_owned()))
24	        } else {
25	            Err(DomainError::InvalidSlug(input.to_owned()))
26	        }
27	    }
28	    pub fn as_str(&self) -> &str {
29	        &self.0
30	    }
31	}
