346	        assert!(Project::new(ProjectId::from_parts(u(7), u(3)), team, Slug::parse("p").unwrap(), "P", now).is_ok());
347	    }
348	    #[test]
349	    fn new_nodes_start_active() {
350	        let now = Utc::now();
351	        let org = Organization::new(OrganizationId::from_uuid(u(1)), Slug::parse("acme").unwrap(), "Acme", now).unwrap();
352	        assert_eq!(org.status, NodeStatus::Active);
353	        assert_eq!(org.created_at, now);
354	        assert_eq!(org.updated_at, now);
