48	/// The OIDC authenticator over the in-process JWKS cache (the `memory` backend, D2).
49	pub type Oidc = OidcAuthenticator<HttpJwksFetcher, InMemoryJwksCache, SystemClock>;
50	/// The OIDC authenticator over the external Redis JWKS cache (the `redis` backend, D15).
51	pub type OidcRedis = OidcAuthenticator<HttpJwksFetcher, RedisJwksCache, SystemClock>;
52	
53	/// The one concrete `Authenticator` the composition root wires, chosen by
54	/// `authn.jwks_cache.backend`. The payloads are `Arc`ed because `AppState` (and therefore
55	/// `AuthnSvc`) must be `Clone`, while `OidcAuthenticator` deliberately is not — its JWKS
56	/// provider owns per-issuer single-flight/cooldown state that every `AppState` clone must
57	/// SHARE, not duplicate (a cloned cache would defeat both the cache and the rate limits).
58	#[derive(Clone)]
59	pub enum WiredAuthenticator {
60	    Memory(Arc<Oidc>),
61	    Redis(Arc<OidcRedis>),
62	}
63	
64	#[async_trait]
65	impl Authenticator for WiredAuthenticator {
66	    async fn authenticate(&self, token: &str) -> Result<ValidatedClaims, AuthnError> {
67	        match self {
68	            WiredAuthenticator::Memory(inner) => inner.authenticate(token).await,
69	            WiredAuthenticator::Redis(inner) => inner.authenticate(token).await,
70	        }
71	    }
72	}
