74	/// The fully wired `AuthenticateToken` use case (Tasks 11–12 consume this via
75	/// `AppState.authn` for the middleware `resolve` path and the gRPC `Introspect`).
76	pub type AuthnSvc = AuthenticateToken<WiredAuthenticator, PgExternalIdentityRepository, PgPrincipalRepository, PgMembershipRepository, KernelIdGenerator, SystemClock>;
77	
78	/// Headroom over `max_token_bytes` for the introspect JSON envelope (`{"token":"…"}` —
79	/// braces, quotes, key, and any insignificant whitespace): a request larger than
80	/// `max_token_bytes` + this can never carry a valid token, so the route body limit
81	/// rejects it before JSON parsing (spec H1).
82	const INTROSPECT_BODY_OVERHEAD_BYTES: usize = 1024;
83	
84	#[derive(Clone)]
85	pub struct AppState {
86	    pub db: DatabaseConnection,
87	    pub orgs: OrgSvc,
88	    pub teams: TeamSvc,
89	    pub projects: ProjectSvc,
90	    pub memberships: MembershipSvc,
91	    pub users: UserSvc,
92	    pub authn: AuthnSvc,
93	    /// Route-level body cap for `POST /v1/authn/introspect` (H1): `max_token_bytes` +
94	    /// [`INTROSPECT_BODY_OVERHEAD_BYTES`], computed once at wiring time.
95	    pub introspect_body_limit: usize,
96	}
97	
98	impl AppState {
99	    /// Builds every tenancy service from `db` (each wired to its own Postgres repository —
100	    /// a cheap clone of the same connection pool handle — `KernelIdGenerator`, and
101	    /// `SystemClock`) plus the wired `AuthnSvc` from `cfg.authn`: the OIDC authenticator
102	    /// over the configured JWKS cache backend, the Pg authn repositories, and the
103	    /// per-issuer `JitPolicy`. Fails when the Redis JWKS cache is configured but
104	    /// unreachable (`RedisJwksCache::connect` is the async part) — `IamConfig::validate`
105	    /// has already guaranteed `redis_url` is present and every issuer parses.
106	    pub async fn new(db: DatabaseConnection, cfg: &IamConfig) -> Result<AppState, AuthnError> {
107	        let orgs = OrganizationService::new(PgOrganizationRepository::new(db.clone()), KernelIdGenerator, SystemClock);
108	        let teams = TeamService::new(PgTeamRepository::new(db.clone()), KernelIdGenerator, SystemClock);
109	        let projects = ProjectService::new(PgProjectRepository::new(db.clone()), PgTeamRepository::new(db.clone()), KernelIdGenerator, SystemClock);
110	        let memberships = MembershipService::new(PgMembershipRepository::new(db.clone()), KernelIdGenerator, SystemClock);
111	        let users = CreateUser::new(PgPrincipalRepository::new(db.clone()), KernelIdGenerator, SystemClock);
112	
113	        let authn_cfg = &cfg.authn;
114	        if authn_cfg.accept_invalid_tls {
115	            tracing::warn!("accept_invalid_tls is enabled: TLS certificate verification for IdP discovery/JWKS fetches is DISABLED — test-only configuration, never use in production");
116	        }
117	        let fetcher = HttpJwksFetcher::new(Duration::from_secs(authn_cfg.http_timeout_secs), authn_cfg.accept_invalid_tls)?;
118	        let ttl = Duration::from_secs(authn_cfg.jwks_ttl_secs);
119	        let cooldown = Duration::from_secs(authn_cfg.jwks_refresh_cooldown_secs);
120	        let authenticator = match authn_cfg.jwks_cache.backend {
121	            JwksCacheBackend::Memory => WiredAuthenticator::Memory(Arc::new(OidcAuthenticator::new(
122	                authn_cfg.issuers.clone(),
123	                JwksProvider::new(fetcher, InMemoryJwksCache::new(), SystemClock, ttl, cooldown),
124	                authn_cfg.leeway_secs,
125	                authn_cfg.max_token_bytes,
126	            )?)),
127	            JwksCacheBackend::Redis => {
128	                // `IamConfig::validate` rejects a redis backend without a URL at boot; a
129	                // `None` here is a wiring defect, not an operator error.
130	                let redis_url = authn_cfg
131	                    .jwks_cache
132	                    .redis_url
133	                    .as_deref()
134	                    .ok_or_else(|| AuthnError::Backend("jwks_cache.backend = \"redis\" without redis_url (IamConfig::validate must run first)".into()))?;
135	                let cache = RedisJwksCache::connect(redis_url, authn_cfg.jwks_ttl_secs).await?;
136	                WiredAuthenticator::Redis(Arc::new(OidcAuthenticator::new(
137	                    authn_cfg.issuers.clone(),
138	                    JwksProvider::new(fetcher, cache, SystemClock, ttl, cooldown),
139	                    authn_cfg.leeway_secs,
140	                    authn_cfg.max_token_bytes,
141	                )?))
142	            }
143	        };
144	
145	        let jit_flags = authn_cfg
146	            .issuers
147	            .iter()
148	            .map(|issuer_cfg| Issuer::parse(&issuer_cfg.issuer).map(|issuer| (issuer, issuer_cfg.jit_provisioning)))
149	            .collect::<Result<Vec<_>, _>>()
150	            .map_err(|e| AuthnError::Backend(e.to_string().into()))?;
151	        let authn = AuthenticateToken::new(
152	            authenticator,
153	            PgExternalIdentityRepository::new(db.clone()),
154	            PgPrincipalRepository::new(db.clone()),
155	            PgMembershipRepository::new(db.clone()),
156	            KernelIdGenerator,
157	            SystemClock,
158	            JitPolicy::from_issuers(&jit_flags),
159	        );
160	
161	        Ok(AppState {
162	            db,
163	            orgs,
164	            teams,
165	            projects,
166	            memberships,
167	            users,
168	            authn,
169	            introspect_body_limit: cfg.authn.max_token_bytes + INTROSPECT_BODY_OVERHEAD_BYTES,
170	        })
171	    }
172	}
