174	/// Liveness only — stateless, so it is testable without a database.
175	pub fn health_router() -> Router {
176	    Router::new().route("/healthz", get(healthz))
177	}
178	
179	/// Full HTTP surface: liveness + DB-backed readiness + the `/v1` tenancy API + authn
180	/// introspection. The tenancy routes (organizations/teams/projects/memberships/users) sit
181	/// on their own sub-router carrying the bearer-enforcement `route_layer` (D14 — attached
182	/// HERE, inside `router()`, not in `serve_http`, so the `oneshot` test harness exercises
183	/// it). `/healthz`, `/readyz`, and `POST /v1/authn/introspect` are merged OUTSIDE that
184	/// layer and stay unauthenticated (spec §7.4).
185	pub fn router(state: AppState) -> Router {
186	    let protected = Router::new()
187	        .merge(organizations::router())
188	        .merge(teams::router())
189	        .merge(projects::router())
190	        .merge(memberships::router())
191	        .merge(users::router())
192	        // `route_layer` (not `layer`): the enforcement covers exactly the routes defined
193	        // above and never the merged-in `/healthz`/`/readyz`/introspect or the 404 fallback.
194	        .route_layer(axum::middleware::from_fn_with_state(state.clone(), auth_middleware::require_bearer))
195	        .with_state(state.clone());
196	    let public = Router::new().route("/readyz", get(readyz)).with_state(state.clone());
197	    let authn_api = authn::router(state.introspect_body_limit).with_state(state);
198	    health_router().merge(protected).merge(public).merge(authn_api)
199	}
200	
201	async fn healthz() -> impl IntoResponse {
202	    (StatusCode::OK, Json(json!({ "status": "ok" })))
203	}
204	
205	async fn readyz(State(state): State<AppState>) -> impl IntoResponse {
206	    let ping = state.db.execute(Statement::from_string(state.db.get_database_backend(), "SELECT 1")).await;
207	    match ping {
208	        Ok(_) => (StatusCode::OK, Json(json!({ "status": "ready" }))),
209	        Err(e) => {
210	            tracing::warn!(error = %e, "readiness check failed: database ping error");
211	            (StatusCode::SERVICE_UNAVAILABLE, Json(json!({ "status": "unready" })))
212	        }
213	    }
214	}
215	
216	/// Serve the HTTP surface on `addr` until `shutdown` resolves.
217	pub async fn serve_http(addr: SocketAddr, state: AppState, request_timeout: Duration, shutdown: impl std::future::Future<Output = ()> + Send + 'static) -> std::io::Result<()> {
218	    // `TimeoutLayer::new` is deprecated since tower-http 0.6.7 in favor of
219	    // `with_status_code`; `REQUEST_TIMEOUT` (408) reproduces `new`'s prior default.
220	    let app = router(state)
221	        .layer(TraceLayer::new_for_http())
222	        .layer(TimeoutLayer::with_status_code(StatusCode::REQUEST_TIMEOUT, request_timeout));
223	    let listener = tokio::net::TcpListener::bind(addr).await?;
224	    axum::serve(listener, app).with_graceful_shutdown(shutdown).await
225	}
