3	//! tonic gRPC surface: the well-known `grpc.health.v1.Health` service (via tonic-health), the
4	//! IAM `TenancyService` (task-16 brief, SMA-442), and the `AuthnService` + bearer-enforcement
5	//! layer (SMA-443 Task 12).
6	
7	pub mod authn;
8	pub mod convert;
9	pub mod tenancy;
10	
11	use std::net::SocketAddr;
12	use tonic::transport::Server;
13	use tonic::transport::server::Router as TonicRouter;
14	use tonic_health::ServingStatus;
15	use tower::layer::util::{Identity, Stack};
16	
17	use crate::adapters::http::AppState;
18	use authn::{AuthLayer, AuthnGrpc};
19	use paigasus_proto::paigasus::iam::v1::authn_service_server::AuthnServiceServer;
20	use paigasus_proto::paigasus::iam::v1::tenancy_service_server::TenancyServiceServer;
21	use tenancy::TenancyGrpc;
22	
23	/// Build a health service with the overall server marked SERVING, plus its reporter.
24	/// M0 serves a **static** `SERVING` status — there is no gRPC readiness wiring in scope
25	/// (`/readyz` is HTTP-only, see `adapters::http`). The reporter is returned so the caller
26	/// *could* flip the status later, but threading it through `router`/`serve` to make gRPC
27	/// health dynamic is a deferred M1 concern. The empty service name ("") is the overall
28	/// status that `grpc_health_probe`/k8s query by default.
29	pub async fn health_service() -> (
30	    tonic_health::server::HealthReporter,
31	    tonic_health::pb::health_server::HealthServer<impl tonic_health::pb::health_server::Health>,
32	) {
33	    let (reporter, service) = tonic_health::server::health_reporter();
34	    reporter.set_service_status("", ServingStatus::Serving).await;
35	    (reporter, service)
36	}
37	
38	/// A tonic `Server` router with the health service, the `TenancyService` (Task 16), and the
39	/// `AuthnService` (Task 12) mounted, serving a static `SERVING` health status (see
40	/// `health_service`). The `AuthLayer` wraps the whole server — health and `AuthnService.
41	/// Introspect` are `:path`-exempt from bearer enforcement, every `TenancyService` RPC is not
42	/// (spec §7.4, D14). `main` calls `.serve_with_shutdown`. The reporter is dropped here —
43	/// dynamic readiness is deferred to M1.
44	pub async fn router(state: AppState, timeout: std::time::Duration) -> TonicRouter<Stack<AuthLayer, Identity>> {
45	    let (_reporter, health) = health_service().await;
46	    Server::builder()
47	        .timeout(timeout)
48	        .layer(AuthLayer::new(state.clone()))
49	        .add_service(health)
50	        .add_service(TenancyServiceServer::new(TenancyGrpc::new(state.clone())))
51	        .add_service(AuthnServiceServer::new(AuthnGrpc::new(state)))
52	}
53	
54	/// Serve gRPC on `addr` until `shutdown` resolves. gRPC health is a static `SERVING` for M0
55	/// (see `health_service`); dynamic readiness is a deferred M1 concern.
56	pub async fn serve(addr: SocketAddr, state: AppState, timeout: std::time::Duration, shutdown: impl std::future::Future<Output = ()> + Send + 'static) -> Result<(), tonic::transport::Error> {
57	    router(state, timeout).await.serve_with_shutdown(addr, shutdown).await
58	}
