2	
3	//! `MembershipService`: attach/detach/list principal-to-tenancy-node memberships
4	//! (SMA-442, ADR-0014).
5	
6	use crate::application::error::TenancyError;
7	use crate::application::pagination::Page;
8	use paigasus_iam_core::{Clock, IdGenerator, Membership, MembershipRecord, MembershipRepository, PrincipalId, TenancyNodeRef};
9	use paigasus_kernel::Prn;
10	use uuid::Uuid;
11	
12	/// Which axis to filter a membership listing by — raw PRN strings from the wire, parsed
13	/// the same way `attach`'s arguments are.
14	#[derive(Debug, Clone, PartialEq, Eq)]
15	pub enum MembershipFilter {
16	    Principal(String),
17	    Node(String),
18	}
19	
20	/// Parses a raw principal PRN string: must be syntactically valid (else `InvalidPrn` with
21	/// the kernel's stable error-kind token), and must be service `"iam"`, resource type
22	/// `"principal"` (else `InvalidPrn` with the PRN's canonical form).
23	fn parse_principal_prn(raw: &str) -> Result<PrincipalId, TenancyError> {
24	    let prn = Prn::parse(raw).map_err(|e| TenancyError::InvalidPrn(e.kind().to_owned()))?;
25	    if prn.service() != "iam" || prn.resource_type() != "principal" {
26	        return Err(TenancyError::InvalidPrn(prn.canonical()));
27	    }
28	    Ok(PrincipalId::from_prn(prn))
29	}
30	
31	/// Parses a raw tenancy-node PRN string into a typed node ref (organization/team/project).
32	/// A `DomainError` from `TenancyNodeRef::from_prn` (wrong resource type, malformed org slot)
33	/// auto-converts into `TenancyError::InvalidPrn`.
34	fn parse_node_prn(raw: &str) -> Result<TenancyNodeRef, TenancyError> {
35	    let prn = Prn::parse(raw).map_err(|e| TenancyError::InvalidPrn(e.kind().to_owned()))?;
36	    Ok(TenancyNodeRef::from_prn(prn)?)
37	}
38	
39	/// Membership lifecycle use cases: attach a principal to a tenancy node, detach, list.
40	/// Generic-DI-by-value (`M`embership repository, `I`d generator, `C`lock) — no `Arc<dyn>`,
41	/// mirroring `OrganizationService`/`TeamService`/`ProjectService` (design doc §5).
42	#[derive(Clone)]
43	pub struct MembershipService<M, I, C> {
44	    repo: M,
45	    ids: I,
46	    clock: C,
47	}
48	
49	impl<M, I, C> MembershipService<M, I, C>
50	where
51	    M: MembershipRepository,
52	    I: IdGenerator,
53	    C: Clock,
54	{
55	    pub fn new(repo: M, ids: I, clock: C) -> Self {
56	        Self { repo, ids, clock }
57	    }
58	
59	    /// Attaches `principal_prn` to `node_prn`. This only parses/validates the wire PRNs and
60	    /// mints the membership id/timestamp — every existence/guard check (principal exists,
61	    /// node exists, prn byte-match, effectively-active, org-membership invariant,
62	    /// duplicate) happens in-txn in `repo.attach` (D8, port doc contract).
63	    pub async fn attach(&self, principal_prn: &str, node_prn: &str) -> Result<MembershipRecord, TenancyError> {
64	        let principal_id = parse_principal_prn(principal_prn)?;
65	        let node = parse_node_prn(node_prn)?;
66	
67	        let id = self.ids.new_membership_id();
68	        let now = self.clock.now();
69	        let membership = Membership::new(id, principal_id, node, now);
70	
71	        Ok(self.repo.attach(&membership).await?)
72	    }
73	
74	    /// Detaches a membership by id. `NotFound` if missing. Detaching an org membership
75	    /// cascades: the repo also detaches the principal's team/project memberships scoped to
76	    /// that org, in one transaction (rule 5).
77	    pub async fn detach(&self, id: Uuid) -> Result<(), TenancyError> {
78	        Ok(self.repo.detach(id).await?)
79	    }
80	
81	    /// Lists memberships by principal or node, `ORDER BY created_at, id` (design doc §5.1
82	    /// rule 9).
83	    pub async fn list(&self, filter: MembershipFilter, page: Page) -> Result<Vec<MembershipRecord>, TenancyError> {
84	        match filter {
85	            MembershipFilter::Principal(raw) => {
86	                let principal_id = parse_principal_prn(&raw)?;
87	                Ok(self.repo.list_by_principal(principal_id.uuid(), page.limit, page.offset).await?)
88	            }
89	            MembershipFilter::Node(raw) => {
90	                let node = parse_node_prn(&raw)?;
91	                Ok(self.repo.list_by_node(&node, page.limit, page.offset).await?)
92	            }
93	        }
94	    }
95	}
