3	//! Bearer-enforcement middleware for the protected `/v1` HTTP surface (spec §7.4, D14).
4	//! Extracts `Authorization: Bearer <token>` — the ONLY accepted credential source (no
5	//! cookies, no query parameters) — runs it through `AuthnSvc::resolve(.., Enabled)` (which
6	//! JIT-provisions an unknown identity, AC 2), and, on success, inserts an [`AuthContext`]
7	//! request extension for downstream handlers. Every rejection short-circuits through the
8	//! shared `AuthnApiError` funnel (D12): status and body are always 401 `invalid_token`;
9	//! only the `WWW-Authenticate` challenge distinguishes a fully-absent `Authorization`
10	//! header (bare `Bearer`, RFC 6750 §3.1) from a present-but-rejected credential
11	//! (`Bearer error="invalid_token"`). The token itself is never logged (nothing here logs
12	//! it, and `AuthnError`'s own contract keeps claim/token material out of its `Display`).
13	
14	use axum::extract::{Request, State};
15	use axum::http::{HeaderValue, header};
16	use axum::middleware::Next;
17	use axum::response::{IntoResponse, Response};
18	use paigasus_iam_core::{AuthnError, TokenDefect};
19	
20	use super::AppState;
21	use super::authn::AuthnApiError;
22	use crate::adapters::auth::{AuthContext, bearer_from_headers};
23	use crate::application::authenticate_token::Provisioning;
24	
25	/// Enforces a valid bearer token on the request before it reaches a protected handler
26	/// (D14 — wired via `route_layer` inside `router()`, so the `oneshot` test harness
27	/// exercises it too). Applied only to the tenancy sub-router; `/healthz`, `/readyz`, and
28	/// `POST /v1/authn/introspect` stay outside it (spec §7.4).
29	pub async fn require_bearer(State(state): State<AppState>, mut request: Request, next: Next) -> Response {
30	    let header_present = request.headers().contains_key(header::AUTHORIZATION);
31	    let Some(token) = bearer_from_headers(request.headers()) else {
32	        // Absent or unusable credentials get the SAME 401 status and `invalid_token` body
33	        // (the error contract stays uniform, D12); only the challenge header distinguishes
34	        // a client that sent NO credentials at all (bare `Bearer`, RFC 6750 §3.1 — no error
35	        // attribute when the request lacks authentication information) from one whose
36	        // header or token was present but rejected (`Bearer error="invalid_token"`).
37	        let mut response = AuthnApiError(AuthnError::InvalidToken(TokenDefect::Malformed)).into_response();
38	        if !header_present {
39	            response.headers_mut().insert(header::WWW_AUTHENTICATE, HeaderValue::from_static("Bearer"));
40	        }
41	        return response;
42	    };
43	
44	    match state.authn.resolve(&token, Provisioning::Enabled).await {
45	        Ok(principal) => {
46	            request.extensions_mut().insert(AuthContext {
47	                principal_id: principal.principal_id,
48	                issuer: principal.issuer,
49	                subject: principal.subject,
50	            });
51	            next.run(request).await
52	        }
53	        Err(err) => AuthnApiError(err).into_response(),
54	    }
55	}
